import React, { useState, useEffect } from 'react';
import { fetchAllApplicants } from './api/apiClient';
import './index.css';

function RecruiterDashboard({ token }) {
  const [applicants, setApplicants] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const loadApplicants = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await fetchAllApplicants(token);
      setApplicants(res.data);
    } catch (err) {
      setError('Failed to fetch applicants.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadApplicants();
  }, [token]);

  return (
    <div className="dashboard-container">
      <h2>Recruiter Dashboard</h2>
      <p>Welcome, Recruiter! Here you can view and manage applicants.</p>
      <div className="recruiter-actions">
        <button onClick={loadApplicants} disabled={loading}>
          {loading ? 'Refreshing...' : 'Refresh Applicants'}
        </button>
        <button>Search Applicants</button>
        <button>Export Data</button>
      </div>
      {error && <div style={{ color: 'red' }}>{error}</div>}
      <div className="applicant-list">
        {applicants.length > 0 ? (
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>LinkedIn</th>
              </tr>
            </thead>
            <tbody>
              {applicants.map((applicant) => (
                <tr key={applicant.id}>
                  <td>{applicant.name}</td>
                  <td>{applicant.email}</td>
                  <td>
                    <a href={applicant.linkedin_url} target="_blank" rel="noopener noreferrer">
                      Profile
                    </a>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No applicants loaded yet.</p>
        )}
      </div>
    </div>
  );
}

export default RecruiterDashboard;
